// Ring buffer simple moving average
// Uses circular buffer with wrap-around write index — no array shifting
// Average stays 0.0 until buffer has BufferSize samples collected

Init := FALSE;

// --- Init on first cycle ---
IF NOT _initDone THEN
	_writeIdx := 0;
	_count := 0;
	_sum := 0.0;
	_initDone := TRUE;
	Init := TRUE;
END_IF

// --- Ring buffer write ---
// Subtract overwritten value from running sum if buffer is full
IF _count >= BufferSize THEN
	_sum := _sum - _buffer[_writeIdx];
ELSE
	_count := _count + 1;
END_IF

// Write new value and add to running sum
_buffer[_writeIdx] := Value;
_sum := _sum + Value;

// Wrap-around write index
_writeIdx := (_writeIdx + 1) MOD BufferSize;

// --- Average output ---
// Wait until buffer has BufferSize samples before producing valid output
IF _count >= BufferSize THEN
	Average := _sum / INT_TO_LREAL(_count);
ELSE
	Average := 0.0;
END_IF

(* revision history
factory  .  may 2026    rev 1.0
	original version

*)

FOR _i := 0 TO 99 BY 1 DO
	_buffer[_i] := 0.0;
END_FOR

_i := 0;
_writeIdx := 0;
_count := 0;
_sum := 0.0;
Average := 0.0;
Init := FALSE;
_initDone := FALSE;

_Reset := TRUE;

// Test method invocations
_reset();
PRG_TEST.TestLog(Message := 'FB_MovingAverage_Test: StartupFill_ReturnsZero');
StartupFill_ReturnsZero();
PRG_TEST.TestLog(Message := 'FB_MovingAverage_Test: ConstantInput_ProducesExpected');
ConstantInput_ProducesExpected();
PRG_TEST.TestLog(Message := 'FB_MovingAverage_Test: SlidingWindow_CorrectAverage');
SlidingWindow_CorrectAverage();
PRG_TEST.TestLog(Message := 'FB_MovingAverage_Test: WindowWrap_CorrectAfterOverwrite');
WindowWrap_CorrectAfterOverwrite();
PRG_TEST.TestLog(Message := 'FB_MovingAverage_Test: ZeroInput_AfterFill_BringsAverageDown');
ZeroInput_AfterFill_BringsAverageDown();
PRG_TEST.TestLog(Message := 'FB_MovingAverage_Test: InitFlag_TrueOnFirstCall_FalseOnSecondCall');
InitFlag_TrueOnFirstCall_FalseOnSecondCall();
PRG_TEST.TestLog(Message := 'FB_MovingAverage_Test: NegativeValues_AveragedCorrectly');
NegativeValues_AveragedCorrectly();
PRG_TEST.TestLog(Message := 'FB_MovingAverage_Test: WarmReset_ResumesWithoutReconfig');
WarmReset_ResumesWithoutReconfig();

// Reset FB_MovingAverage runtime state through its public API
fbUnderTest._Reset();
fbUnderTest.BufferSize := 5;
fbUnderTest.Value := 0.0;

TEST('ConstantInput_ProducesExpected');

_reset();
fbUnderTest.BufferSize := 4;

// Fill buffer with constant value 100.0
FOR _idx := 1 TO 4 DO
	fbUnderTest.Value := 100.0;
	fbUnderTest();
END_FOR

// After fill, Average should be 100.0
AssertEquals_LREAL(Expected := 100.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Constant input 100: Average = 100 after fill');

// Push more of same value, average stays
FOR _idx := 1 TO 6 DO
	fbUnderTest.Value := 100.0;
	fbUnderTest();
END_FOR
AssertEquals_LREAL(Expected := 100.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Constant input 100: Average = 100 after 10 more cycles');

TEST_FINISHED();

TEST('InitFlag_TrueOnFirstCall_FalseOnSecondCall');

_reset();

(* Cycle 1: first call - Init should be TRUE *)
fbUnderTest();
AssertTrue(fbUnderTest.Init, 'Init should be TRUE on first cycle');

(* Cycle 2: second call - Init should be FALSE *)
fbUnderTest();
AssertFalse(fbUnderTest.Init, 'Init should be FALSE on second cycle');

TEST_FINISHED();

TEST('NegativeValues_AveragedCorrectly');

_reset();

(* Negative values in the window should be averaged correctly *)
fbUnderTest.BufferSize := 3;
fbUnderTest.Value := -10.0; fbUnderTest();
fbUnderTest.Value := -20.0; fbUnderTest();
fbUnderTest.Value := -30.0; fbUnderTest();
AssertTrue(fbUnderTest.Average < 0.0, 'Average of negative values should be negative');
(* Verify precise computation: (-10 + -20 + -30) / 3 = -20.0 *)
AssertEquals_LREAL(Expected := -20.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Average of -10,-20,-30 = -20.0');

TEST_FINISHED();

TEST('SlidingWindow_CorrectAverage');

_reset();
fbUnderTest.BufferSize := 4;

// Fill buffer: 10, 20, 30, 40 -> Average = (10+20+30+40)/4 = 25.0
fbUnderTest.Value := 10.0; fbUnderTest();
fbUnderTest.Value := 20.0; fbUnderTest();
fbUnderTest.Value := 30.0; fbUnderTest();
fbUnderTest.Value := 40.0; fbUnderTest();
AssertEquals_LREAL(Expected := 25.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Fill 10,20,30,40: Average = 25.0');

// Push 50 -> replaces 10 -> Buffer: 50,20,30,40 -> Average = (50+20+30+40)/4 = 35.0
fbUnderTest.Value := 50.0; fbUnderTest();
AssertEquals_LREAL(Expected := 35.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Push 50 (replaces 10): Average = 35.0');

// Push 60 -> replaces 20 -> Buffer: 50,60,30,40 -> Average = (50+60+30+40)/4 = 45.0
fbUnderTest.Value := 60.0; fbUnderTest();
AssertEquals_LREAL(Expected := 45.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Push 60 (replaces 20): Average = 45.0');

// Push 70 -> replaces 30 -> Buffer: 50,60,70,40 -> Average = (50+60+70+40)/4 = 55.0
fbUnderTest.Value := 70.0; fbUnderTest();
AssertEquals_LREAL(Expected := 55.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Push 70 (replaces 30): Average = 55.0');

// Push 80 -> replaces 40 -> Buffer: 50,60,70,80 -> Average = (50+60+70+80)/4 = 65.0
fbUnderTest.Value := 80.0; fbUnderTest();
AssertEquals_LREAL(Expected := 65.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Push 80 (replaces 40): Average = 65.0');

TEST_FINISHED();

TEST('StartupFill_ReturnsZero');

_reset();
fbUnderTest.BufferSize := 5;

// Before buffer is full, Average should be 0.0
fbUnderTest.Value := 10.0;
fbUnderTest();
AssertEquals_LREAL(Expected := 0.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := '1st sample: Average = 0 (filling)');

fbUnderTest.Value := 20.0;
fbUnderTest();
AssertEquals_LREAL(Expected := 0.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := '2nd sample: Average = 0 (filling)');

fbUnderTest.Value := 30.0;
fbUnderTest();
AssertEquals_LREAL(Expected := 0.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := '3rd sample: Average = 0 (filling)');

fbUnderTest.Value := 40.0;
fbUnderTest();
AssertEquals_LREAL(Expected := 0.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := '4th sample: Average = 0 (filling, one more to go)');

// 5th sample fills the buffer
fbUnderTest.Value := 50.0;
fbUnderTest();
AssertEquals_LREAL(Expected := 30.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := '5th sample: Average = (10+20+30+40+50)/5 = 30.0');

TEST_FINISHED();

TEST('WarmReset_ResumesWithoutReconfig');

_reset();
fbUnderTest.BufferSize := 3;
fbUnderTest.Value := 10.0;
fbUnderTest();
fbUnderTest.Value := 20.0;
fbUnderTest();
fbUnderTest.Value := 30.0;
fbUnderTest();
AssertEquals_LREAL(Expected := 20.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Average before reset');

fbUnderTest._Reset();
fbUnderTest();

AssertTrue(Condition := fbUnderTest.Init, Message := 'Reset reproduces first-cycle Init');
AssertEquals_LREAL(Expected := 0.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Reset clears the prior moving window');

TEST_FINISHED();

TEST('WindowWrap_CorrectAfterOverwrite');

_reset();
fbUnderTest.BufferSize := 3;

// Fill: 10, 20, 30 -> Average = 20.0
fbUnderTest.Value := 10.0; fbUnderTest();
fbUnderTest.Value := 20.0; fbUnderTest();
fbUnderTest.Value := 30.0; fbUnderTest();
AssertEquals_LREAL(Expected := 20.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Fill 10,20,30: Average = 20.0');

// Push many values: 40, 50, 60, 70, 80 each replacing oldest
// After 40: (40+20+30)/3 = 30.0
fbUnderTest.Value := 40.0; fbUnderTest();
AssertEquals_LREAL(Expected := 30.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Wrap: push 40 replaces 10 = 30.0');

// After 50: (40+50+30)/3 = 40.0
fbUnderTest.Value := 50.0; fbUnderTest();
AssertEquals_LREAL(Expected := 40.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Wrap: push 50 replaces 20 = 40.0');

// After 60: (40+50+60)/3 = 50.0
fbUnderTest.Value := 60.0; fbUnderTest();
AssertEquals_LREAL(Expected := 50.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Wrap: push 60 replaces 30 = 50.0');

// After 70: (70+50+60)/3 = 60.0
fbUnderTest.Value := 70.0; fbUnderTest();
AssertEquals_LREAL(Expected := 60.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Wrap: push 70 replaces 40 = 60.0');

// After 80: (70+80+60)/3 = 70.0
fbUnderTest.Value := 80.0; fbUnderTest();
AssertEquals_LREAL(Expected := 70.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Wrap: push 80 replaces 50 = 70.0');

TEST_FINISHED();

TEST('ZeroInput_AfterFill_BringsAverageDown');

_reset();
fbUnderTest.BufferSize := 4;

// Fill with 100: Average = 100.0
FOR _idx := 1 TO 4 DO
	fbUnderTest.Value := 100.0;
	fbUnderTest();
END_FOR
AssertEquals_LREAL(Expected := 100.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Fill: Average = 100.0');

// Push zero, replaces 100 (oldest) -> (0+100+100+100)/4 = 75.0
fbUnderTest.Value := 0.0; fbUnderTest();
AssertEquals_LREAL(Expected := 75.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Zero replaces first 100: Average = 75.0');

// Push another zero -> (0+0+100+100)/4 = 50.0
fbUnderTest.Value := 0.0; fbUnderTest();
AssertEquals_LREAL(Expected := 50.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Zero replaces second 100: Average = 50.0');

// Push another zero -> (0+0+0+100)/4 = 25.0
fbUnderTest.Value := 0.0; fbUnderTest();
AssertEquals_LREAL(Expected := 25.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'Zero replaces third 100: Average = 25.0');

// Push another zero -> (0+0+0+0)/4 = 0.0
fbUnderTest.Value := 0.0; fbUnderTest();
AssertEquals_LREAL(Expected := 0.0, Actual := fbUnderTest.Average, Delta := 0.0001, Message := 'All zeros: Average = 0.0');

TEST_FINISHED();
